 private static StressGaugeBlockEntity gauge(ServerLevel level){return LoadedLevelAccess.blockEntity(level,G) instanceof StressGaugeBlockEntity gauge?gauge:null;}
 private static PortableStorageInterfaceBlockEntity psi(ServerLevel level){return LoadedLevelAccess.blockEntity(level,S) instanceof PortableStorageInterfaceBlockEntity endpoint?endpoint:null;}
 private static CuckooClockBlockEntity clock(ServerLevel level){return LoadedLevelAccess.blockEntity(level,CLOCK) instanceof CuckooClockBlockEntity clock?clock:null;}
 private static ControlledContraptionEntity moving(ServerLevel level){return LoadedLevelAccess.blockEntity(level,BEARING) instanceof MechanicalBearingBlockEntity bearing?bearing.getMovedContraption():null;}
 private static long mounted(ServerLevel level){var entity=moving(level);if(entity==null||entity.getContraption()==null)return -1;long count=0;for(var view:entity.getContraption().getStorage().getAllItems())if(view.getResource().equals(net.fabricmc.fabric.api.transfer.v1.item.ItemVariant.of(named(Items.DIAMOND,1))))count+=view.getAmount();return count;}
 private static long received(ServerLevel level){long count=0;for(var pos:List.of(S.below(),RECEIPT))if(LoadedLevelAccess.blockEntity(level,pos) instanceof net.minecraft.world.Container container)for(int slot=0;slot<container.getContainerSize();slot++){var item=container.getItem(slot);if(ItemStack.isSameItemSameComponents(item,named(Items.DIAMOND,1)))count+=item.getCount();}return count;}
 private static boolean done(ServerLevel level,String id){var holder=level.getServer().getAdvancements().get(Create.asResource(id));return holder!=null&&actual(level).getAdvancements().getOrStartProgress(holder).isDone();}
 private static ServerPlayer actual(ServerLevel level){return level.getServer().getPlayerList().getPlayers().getFirst();}
 private static ItemStack named(Item item,int count){var stack=new ItemStack(item,count);stack.set(DataComponents.CUSTOM_NAME,Component.literal(NAME));return stack;}
 private static void select(ClientGameTestContext c,TestSingleplayerContext w,int key,int slot){c.getInput().pressKey(key);c.waitFor(client->client.player.getInventory().getSelectedSlot()==slot,220);c.waitFor(client->{var state=new FirstPersonHandsAndItemsRenderState();client.player.firstPersonHandsAndItems().extractRenderState(client.player,.5f,state);return state.mainHandItem.getItem()==client.player.getMainHandItem().getItem();},220);await(c,w,level->actual(level).getInventory().getSelectedSlot()==slot,220,"Actual physical native hotbar input failed client/server acknowledgement");}
 private static void empty(ClientGameTestContext c,TestSingleplayerContext w){int slot=c.computeOnClient(client->java.util.stream.IntStream.range(0,9).filter(index->client.player.getInventory().getItem(index).isEmpty()).findFirst().orElseThrow());select(c,w,InputConstants.KEY_1+slot,slot);await(c,w,level->actual(level).getMainHandItem().isEmpty(),220,"Actual native empty hand selection failed");}
 private static void stand(ClientGameTestContext c,TestSingleplayerContext w,double x,double z){w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("tp @p "+x+" 5 "+z);c.waitFor(client->!client.player.isSpectator()&&client.player.onGround()&&Math.abs(client.player.getX()-x)<.1&&Math.abs(client.player.getZ()-z)<.1,250);}
 private static void use(ClientGameTestContext c,BlockPos pos,Vec3 point){look(c,point);c.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(pos),250);c.getInput().pressKey(options->options.keyUse);}
 private static void look(ClientGameTestContext c,Vec3 point){var angle=c.computeOnClient(client->{var delta=point.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});c.getInput().lookAt(angle.x,angle.y);}
 private static void screenshot(ClientGameTestContext c,String name){c.waitFor(client->client.gui.overlay()==null,200);c.runOnClient(client->client.gui.hud.getChat().clearMessages(false));c.takeScreenshot(name);}
 private static void await(ClientGameTestContext c,TestSingleplayerContext w,Predicate<ServerLevel> predicate,int ticks,String failure){var done=new AtomicBoolean();for(int tick=0;tick<ticks;tick++){w.getServer().runOnServer(ignored->done.set(predicate.test(w.getConnection().getServerLevel())));if(done.get())return;c.waitTicks(1);}throw new AssertionError(failure);}
